+
+.product-card__wishlist.is-wishlisted { color: var(--color-sale); }
+
+.product-card__wishlist svg { pointer-events: none; }
+
+.product-card__wishlist.is-wishlisted svg { fill: currentColor; }
+
+.product-card__wishlist:focus-visible {
