+
+  --radius-sm:  4px;
+  --radius-md:  8px;
+  --radius-lg:  12px;
+  --radius-xl:  20px;
+  --radius-full: 9999px;
+
+  --transition-fast: 120ms ease;
+  --transition:      200ms ease;
+  --transition-slow: 350ms ease;
+
+  --container-max: 1280px;
+  --container-pad: clamp(1rem, 4vw, 2.5rem);
+
+  --header-height: 64px;
+  --announcement-height: 40px;
+}
+
+/* ===== Reset ===== */
+*,
+*::before,
+*::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
+
+body {
+  font-family: var(--font-sans);
+  background: var(--color-bg);
+  color: var(--color-text-primary);
+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+  -moz-osx-font-smoothing: grayscale;
+}
+
+img, video { display: block; max-width: 100%; }
+
+a { color: inherit; text-decoration: none; }
+
+ul { list-style: none; }
+
+button {
+  cursor: pointer;
+  border: none;
+  background: none;
+  font: inherit;
+  color: inherit;
+}
+
+input, select, textarea {
+  font: inherit;
+  color: inherit;
+}
+
+/* ===== Utilities ===== */
+.visually-hidden {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+  border: 0;
+}
+
+.container {
+  max-width: var(--container-max);
+  margin-inline: auto;
+  padding-inline: var(--container-pad);
+}
+
+.section {
+  padding-block: clamp(3rem, 6vw, 5rem);
+}
+
+/* ===== Skip Link ===== */
+.skip-link {
+  position: absolute;
+  top: -100px;
+  left: 1rem;
+  z-index: 1000;
+  padding: 0.625rem 1.25rem;
+  background: var(--color-brand);
+  color: var(--color-text-inverse);
+  border-radius: var(--radius-md);
+  font-size: 0.875rem;
+  font-weight: 600;
+  transition: top var(--transition-fast);
+  outline: 3px solid transparent;
+}
+
+.skip-link:focus {
+  top: 1rem;
+  outline: 3px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+/* ===== Focus Styles ===== */
+:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 3px;
+}
+
+/* ===== Buttons ===== */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 0.5rem;
+  padding: 0.75rem 1.75rem;
+  border-radius: var(--radius-md);
+  font-size: 0.875rem;
+  font-weight: 600;
+  letter-spacing: 0.03em;
+  transition: background var(--transition), color var(--transition),
+              transform var(--transition-fast), box-shadow var(--transition);
+  white-space: nowrap;
+  text-decoration: none;
+  cursor: pointer;
+}
+
+.btn:focus-visible {
+  outline: 2px solid currentColor;
+  outline-offset: 3px;
+}
+
+.btn--primary {
+  background: var(--color-brand);
+  color: var(--color-text-inverse);
+  border: 2px solid var(--color-brand);
+}
+
+.btn--primary:hover {
+  background: #2c2c2a;
+  border-color: #2c2c2a;
+  transform: translateY(-1px);
+  box-shadow: var(--shadow-md);
+}
+
+.btn--primary:active { transform: translateY(0); }
+
+.btn--outline {
+  background: transparent;
+  color: var(--color-text-inverse);
+  border: 2px solid rgba(255,255,255,0.7);
+}
+
+.btn--outline:hover {
+  background: rgba(255,255,255,0.12);
+  border-color: white;
+}
+
+.btn--outline-dark {
+  background: transparent;
+  color: var(--color-brand);
+  border: 2px solid var(--color-brand);
+}
+
+.btn--outline-dark:hover {
+  background: var(--color-brand);
+  color: var(--color-text-inverse);
+}
+
+.btn--ghost {
+  background: transparent;
+  color: var(--color-brand);
+  border: 2px solid transparent;
+  padding-inline: 0.25rem;
+}
+
+.btn--ghost:hover { color: var(--color-accent-dark); }
+
+.btn--full { width: 100%; }
+
+.btn--sm {
+  padding: 0.5rem 1.25rem;
+  font-size: 0.8125rem;
+}
+
+.icon-btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 40px;
+  height: 40px;
+  border-radius: var(--radius-md);
+  color: var(--color-text-primary);
+  transition: background var(--transition), color var(--transition);
+  position: relative;
+}
+
+.icon-btn:hover { background: var(--color-surface-alt); }
+
+.icon-btn:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 2px;
+}
+
+/* ===== Announcement Bar ===== */
+.announcement-bar {
+  background: var(--color-brand);
+  color: var(--color-text-inverse);
+  text-align: center;
+  padding: 0;
+  height: var(--announcement-height);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.announcement-bar__inner {
+  display: flex;
+  align-items: center;
+  gap: 1.5rem;
+  font-size: 0.8rem;
+  letter-spacing: 0.06em;
+  font-weight: 500;
+  text-transform: uppercase;
+}
+
+.announcement-bar__divider {
+  opacity: 0.4;
+  font-size: 0.7rem;
+}
+
+/* ===== Header ===== */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: rgba(255,255,255,0.96);
+  backdrop-filter: blur(12px);
+  -webkit-backdrop-filter: blur(12px);
+  border-bottom: 1px solid var(--color-border);
+  height: var(--header-height);
+}
+
+.header-inner {
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  align-items: center;
+  height: 100%;
+}
+
+.header-logo {
+  display: flex;
+  align-items: center;
+  gap: 0.625rem;
+  font-family: var(--font-serif);
+  font-size: 1.375rem;
+  font-weight: 600;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--color-brand);
+  text-decoration: none;
+}
+
+.header-logo__mark {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  width: 28px;
+  height: 28px;
+}
+
+.header-nav {
+  display: flex;
+  align-items: center;
+  gap: 0.25rem;
+}
+
+.header-nav__link {
+  padding: 0.4rem 0.875rem;
+  font-size: 0.875rem;
+  font-weight: 500;
+  color: var(--color-text-secondary);
+  border-radius: var(--radius-sm);
+  transition: color var(--transition), background var(--transition);
+  letter-spacing: 0.01em;
+}
+
+.header-nav__link:hover {
+  color: var(--color-brand);
+  background: var(--color-surface-alt);
+}
+
+.header-nav__link:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 2px;
+}
+
+.header-nav__link--sale { color: var(--color-sale); }
+.header-nav__link--sale:hover { color: var(--color-sale); background: var(--color-sale-bg); }
+
+.header-actions {
+  display: flex;
+  align-items: center;
+  justify-content: flex-end;
+  gap: 0.25rem;
+}
+
+.cart-badge {
+  position: absolute;
+  top: 4px;
+  right: 4px;
+  background: var(--color-sale);
+  color: white;
+  border-radius: var(--radius-full);
+  font-size: 0.65rem;
+  font-weight: 700;
+  min-width: 18px;
+  height: 18px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  padding-inline: 4px;
+  line-height: 1;
+  pointer-events: none;
+}
+
+.cart-badge[data-count="0"] { display: none; }
+
+.mobile-menu-btn { display: none; }
+
+/* ===== Mobile Nav Drawer ===== */
+.mobile-nav {
+  display: none;
+  position: fixed;
+  inset: 0;
+  z-index: 200;
+}
+
+.mobile-nav.is-open { display: block; }
+
+.mobile-nav__backdrop {
+  position: absolute;
+  inset: 0;
+  background: rgba(0,0,0,0.4);
+}
+
+.mobile-nav__panel {
+  position: absolute;
+  top: 0;
+  left: 0;
+  bottom: 0;
+  width: min(320px, 85vw);
+  background: var(--color-surface);
+  overflow-y: auto;
+  padding: 1.5rem;
+  display: flex;
+  flex-direction: column;
+  gap: 1.5rem;
+}
+
+.mobile-nav__header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+}
+
+.mobile-nav__logo {
+  font-family: var(--font-serif);
+  font-size: 1.25rem;
+  font-weight: 600;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+}
+
+.mobile-nav__links {
+  display: flex;
+  flex-direction: column;
+  gap: 0.25rem;
+}
+
+.mobile-nav__link {
+  display: block;
+  padding: 0.75rem 1rem;
+  font-size: 1rem;
+  font-weight: 500;
+  border-radius: var(--radius-md);
+  transition: background var(--transition), color var(--transition);
+}
+
+.mobile-nav__link:hover { background: var(--color-surface-alt); }
+.mobile-nav__link--sale { color: var(--color-sale); }
+
+/* ===== Hero ===== */
+.hero {
+  position: relative;
+  min-height: clamp(480px, 65vh, 720px);
+  display: flex;
+  align-items: center;
+  overflow: hidden;
+  background: #1c1612;
+}
+
+.hero__bg {
+  position: absolute;
+  inset: 0;
+  background:
+    linear-gradient(110deg,
+      rgba(18,14,10,0.88) 0%,
+      rgba(18,14,10,0.55) 50%,
+      rgba(18,14,10,0.2) 100%),
+    url('https://picsum.photos/seed/luminary-hero/1400/720') center/cover no-repeat;
+  transform: scale(1.02);
+  transition: transform 8s ease;
+}
+
+.hero:hover .hero__bg { transform: scale(1.0); }
+
+.hero__content {
+  position: relative;
+  z-index: 1;
+  max-width: 600px;
+  padding-block: 4rem;
+}
+
+.hero__eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.625rem;
+  font-size: 0.75rem;
+  font-weight: 600;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: 1.25rem;
+}
+
+.hero__eyebrow::before {
+  content: '';
+  display: block;
+  width: 28px;
+  height: 1px;
+  background: var(--color-accent);
+}
+
+.hero__heading {
+  font-family: var(--font-serif);
+  font-size: clamp(2.5rem, 5.5vw, 4rem);
+  font-weight: 600;
+  line-height: 1.1;
+  color: white;
+  margin-bottom: 1.25rem;
+  letter-spacing: -0.01em;
+}
+
+.hero__heading em {
+  font-style: italic;
+  color: #d4b87a;
+}
+
+.hero__subtext {
+  font-size: clamp(1rem, 1.5vw, 1.125rem);
+  color: rgba(255,255,255,0.8);
+  max-width: 440px;
+  margin-bottom: 2.25rem;
+  font-weight: 300;
+  line-height: 1.7;
+}
+
+.hero__actions {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+  flex-wrap: wrap;
+}
+
+.hero__scroll-hint {
+  position: absolute;
+  bottom: 2rem;
+  left: 50%;
+  transform: translateX(-50%);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 0.5rem;
+  color: rgba(255,255,255,0.5);
+  font-size: 0.7rem;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+}
+
+.hero__scroll-arrow {
+  width: 20px;
+  height: 20px;
+  animation: bounceDown 1.6s ease infinite;
+}
+
+@keyframes bounceDown {
+  0%, 100% { transform: translateY(0); }
+  50% { transform: translateY(6px); }
+}
+
+/* ===== Section Header ===== */
+.section-header {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  margin-bottom: clamp(1.5rem, 3vw, 2.5rem);
+  gap: 1rem;
+  flex-wrap: wrap;
+}
+
+.section-header--center {
+  flex-direction: column;
+  align-items: center;
+  text-align: center;
+}
+
+.section-eyebrow {
+  font-size: 0.75rem;
+  font-weight: 600;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--color-accent-dark);
+  margin-bottom: 0.5rem;
+}
+
+.section-title {
+  font-family: var(--font-serif);
+  font-size: clamp(1.625rem, 3vw, 2.25rem);
+  font-weight: 600;
+  line-height: 1.2;
+  letter-spacing: -0.01em;
+  color: var(--color-brand);
+}
+
+.section-desc {
+  color: var(--color-text-secondary);
+  font-size: 1rem;
+  max-width: 520px;
+  margin-top: 0.625rem;
+  line-height: 1.65;
+}
+
+.view-all-link {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.375rem;
+  font-size: 0.875rem;
+  font-weight: 600;
+  color: var(--color-brand);
+  letter-spacing: 0.02em;
+  padding-bottom: 1px;
+  border-bottom: 1.5px solid var(--color-brand);
+  transition: color var(--transition), border-color var(--transition), gap var(--transition);
+  white-space: nowrap;
+}
+
+.view-all-link:hover {
+  color: var(--color-accent-dark);
+  border-color: var(--color-accent-dark);
+  gap: 0.625rem;
+}
+
+.view-all-link:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 3px;
+  border-bottom-color: transparent;
+}
+
+/* ===== Category Rail ===== */
+.categories {
+  background: var(--color-surface);
+  padding-block: clamp(2rem, 4vw, 3rem);
+  border-bottom: 1px solid var(--color-border);
+}
+
+.category-rail {
+  display: grid;
+  grid-template-columns: repeat(5, 1fr);
+  gap: 1rem;
+}
+
+.category-card {
+  display: block;
+  position: relative;
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  aspect-ratio: 3/4;
+  text-decoration: none;
+  background: var(--color-surface-alt);
+}
+
+.category-card::after {
+  content: '';
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0) 55%);
+  transition: opacity var(--transition);
+}
+
+.category-card:hover::after { opacity: 0.85; }
+
+.category-card:focus-visible {
+  outline: 3px solid var(--color-brand);
+  outline-offset: 3px;
+}
+
+.category-card__bg {
+  position: absolute;
+  inset: 0;
+  background-size: cover;
+  background-position: center;
+  transition: transform var(--transition-slow);
+}
+
+.category-card:hover .category-card__bg { transform: scale(1.06); }
+
+.category-card__label {
+  position: absolute;
+  bottom: 0;
+  left: 0;
+  right: 0;
+  z-index: 1;
+  padding: 1.25rem 1rem 1rem;
+  color: white;
+}
+
+.category-card__name {
+  font-family: var(--font-serif);
+  font-size: clamp(1rem, 1.5vw, 1.1875rem);
+  font-weight: 600;
+  display: block;
+}
+
+.category-card__count {
+  font-size: 0.75rem;
+  opacity: 0.8;
+  font-weight: 400;
+  letter-spacing: 0.03em;
+  margin-top: 0.125rem;
+  display: block;
+}
+
+/* ===== Products Grid ===== */
+.featured-products {
+  background: var(--color-bg);
+}
+
+.products-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: clamp(1rem, 2vw, 1.5rem);
+}
+
+/* ===== Product Card ===== */
+.product-card {
+  background: var(--color-surface);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  border: 1px solid var(--color-border);
+  transition: box-shadow var(--transition), transform var(--transition);
+  display: flex;
+  flex-direction: column;
+}
+
+.product-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-3px);
+}
+
+.product-card__image-wrap {
+  position: relative;
+  aspect-ratio: 3/4;
+  overflow: hidden;
+  background: var(--color-surface-alt);
+}
+
+.product-card__img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transition: transform var(--transition-slow);
+}
+
+.product-card:hover .product-card__img { transform: scale(1.05); }
+
+.product-card__badges {
+  position: absolute;
+  top: 0.75rem;
+  left: 0.75rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+}
+
+.badge {
+  display: inline-block;
+  padding: 0.25rem 0.625rem;
+  border-radius: var(--radius-sm);
+  font-size: 0.7rem;
+  font-weight: 700;
+  letter-spacing: 0.07em;
+  text-transform: uppercase;
+}
+
+.badge--new      { background: var(--color-brand); color: white; }
+.badge--sale     { background: var(--color-sale);  color: white; }
+.badge--trending { background: var(--color-accent); color: #1c1612; }
+.badge--limited  { background: #7c3aed; color: white; }
+
+.product-card__wishlist {
+  position: absolute;
+  top: 0.625rem;
+  right: 0.625rem;
+  background: white;
+  border-radius: var(--radius-full);
+  width: 36px;
+  height: 36px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  box-shadow: var(--shadow-sm);
+  transition: background var(--transition), color var(--transition), transform var(--transition-fast);
+  color: var(--color-text-muted);
+}
+
+.product-card__wishlist:hover {
+  color: var(--color-sale);
+  transform: scale(1.1);
+}
+
+.product-card__wishlist.is-wishlisted { color: var(--color-sale); }
+
+.product-card__wishlist svg { pointer-events: none; }
+
+.product-card__wishlist.is-wishlisted svg { fill: currentColor; }
+
+.product-card__wishlist:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 2px;
+}
+
+.product-card__body {
+  padding: 1rem 1.125rem 1.25rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+  flex: 1;
+}
+
+.product-card__category {
+  font-size: 0.7rem;
+  font-weight: 600;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  color: var(--color-text-muted);
+}
+
+.product-card__name {
+  font-size: 0.9375rem;
+  font-weight: 500;
+  color: var(--color-brand);
+  line-height: 1.35;
+}
+
+.product-card__rating {
+  display: flex;
+  align-items: center;
+  gap: 0.375rem;
+}
+
+.stars {
+  display: flex;
+  align-items: center;
+  gap: 1px;
+  color: var(--color-text-muted);
+}
+
+.star { font-size: 0.8rem; }
+.star--filled { color: #d4a017; }
+
+.review-count {
+  font-size: 0.75rem;
+  color: var(--color-text-muted);
+}
+
+.product-card__footer {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  margin-top: 0.5rem;
+  gap: 0.5rem;
+}
+
+.product-card__price {
+  display: flex;
+  align-items: baseline;
+  gap: 0.5rem;
+}
+
+.price-current {
+  font-size: 1.0625rem;
+  font-weight: 600;
+  color: var(--color-brand);
+}
+
+.price-original {
+  font-size: 0.875rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+
+.price-sale {
+  font-size: 1.0625rem;
+  font-weight: 600;
+  color: var(--color-sale);
+}
+
+.add-to-cart-btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.375rem;
+  padding: 0.5rem 0.875rem;
+  background: var(--color-brand);
+  color: white;
+  border-radius: var(--radius-md);
+  font-size: 0.78rem;
+  font-weight: 600;
+  transition: background var(--transition), transform var(--transition-fast);
+  white-space: nowrap;
+}
+
+.add-to-cart-btn:hover {
+  background: #2c2c2a;
+  transform: translateY(-1px);
+}
+
+.add-to-cart-btn:active { transform: translateY(0); }
+
+.add-to-cart-btn:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 3px;
+}
+
+/* ===== Deals Section ===== */
+.deals {
+  background: #1c1612;
+  color: var(--color-text-inverse);
+  padding-block: clamp(3rem, 6vw, 5rem);
+}
+
+.deals .section-title { color: white; }
+
+.deals .section-eyebrow { color: var(--color-accent); }
+
+.deals-header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1.5rem;
+  margin-bottom: clamp(1.5rem, 3vw, 2.5rem);
+  flex-wrap: wrap;
+}
+
+.deals-view-all {
+  color: rgba(255,255,255,0.75);
+  border-bottom-color: rgba(255,255,255,0.35);
+}
+
+.deals-view-all:hover {
+  color: var(--color-accent);
+  border-bottom-color: var(--color-accent);
+}
+
+.countdown {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+}
+
+.countdown__label {
+  font-size: 0.75rem;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: rgba(255,255,255,0.55);
+}
+
+.countdown__timer {
+  display: flex;
+  align-items: center;
+  gap: 0.375rem;
+}
+
+.countdown__unit {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  background: rgba(255,255,255,0.08);
+  border-radius: var(--radius-sm);
+  padding: 0.375rem 0.625rem;
+  min-width: 48px;
+}
+
+.countdown__number {
+  font-family: var(--font-serif);
+  font-size: 1.375rem;
+  font-weight: 600;
+  line-height: 1;
+  color: white;
+}
+
+.countdown__sublabel {
+  font-size: 0.6rem;
+  font-weight: 500;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  color: rgba(255,255,255,0.45);
+  margin-top: 0.125rem;
+}
+
+.countdown__sep {
+  font-size: 1.25rem;
+  font-weight: 300;
+  color: rgba(255,255,255,0.3);
+  margin-top: -4px;
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: clamp(0.875rem, 2vw, 1.25rem);
+}
+
+/* ===== Deal Card ===== */
+.deal-card {
+  background: rgba(255,255,255,0.05);
+  border: 1px solid rgba(255,255,255,0.1);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  transition: background var(--transition), transform var(--transition), border-color var(--transition);
+  display: flex;
+  flex-direction: column;
+}
+
+.deal-card:hover {
+  background: rgba(255,255,255,0.09);
+  border-color: rgba(255,255,255,0.2);
+  transform: translateY(-3px);
+}
+
+.deal-card__image-wrap {
+  position: relative;
+  aspect-ratio: 4/3;
+  overflow: hidden;
+  background: rgba(255,255,255,0.04);
+}
+
+.deal-card__img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transition: transform var(--transition-slow);
+  opacity: 0.9;
+}
+
+.deal-card:hover .deal-card__img { transform: scale(1.05); opacity: 1; }
+
+.deal-card__discount-badge {
+  position: absolute;
+  top: 0.75rem;
+  left: 0.75rem;
+  background: var(--color-sale);
+  color: white;
+  border-radius: var(--radius-sm);
+  padding: 0.25rem 0.625rem;
+  font-size: 0.75rem;
+  font-weight: 700;
+  letter-spacing: 0.05em;
+}
+
+.deal-card__body {
+  padding: 1rem 1.125rem 1.25rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+}
+
+.deal-card__category {
+  font-size: 0.7rem;
+  font-weight: 600;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  color: rgba(255,255,255,0.4);
+}
+
+.deal-card__name {
+  font-size: 0.9375rem;
+  font-weight: 500;
+  color: rgba(255,255,255,0.9);
+  line-height: 1.35;
+}
+
+.deal-card__price {
+  display: flex;
+  align-items: baseline;
+  gap: 0.625rem;
+  margin-top: 0.25rem;
+}
+
+.deal-card__price-current { 
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: white;
+}
+
+.deal-card__price-original {
+  font-size: 0.875rem;
+  text-decoration: line-through;
+  color: rgba(255,255,255,0.35);
+}
+
+.deal-card__cta {
+  margin-top: auto;
+  padding-top: 0.875rem;
+}
+
+.deal-card__cta-btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.375rem;
+  padding: 0.5rem 1rem;
+  background: rgba(255,255,255,0.1);
+  border: 1px solid rgba(255,255,255,0.18);
+  border-radius: var(--radius-md);
+  font-size: 0.8125rem;
+  font-weight: 600;
+  color: white;
+  transition: background var(--transition), border-color var(--transition);
+  width: 100%;
+  justify-content: center;
+}
+
+.deal-card__cta-btn:hover {
+  background: rgba(255,255,255,0.18);
+  border-color: rgba(255,255,255,0.35);
+}
+
+.deal-card__cta-btn:focus-visible {
+  outline: 2px solid white;
+  outline-offset: 3px;
+}
+
+/* ===== Editorial ===== */
+.editorial {
+  background: var(--color-surface);
+}
+
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-template-rows: 1fr;
+  gap: clamp(1rem, 2vw, 1.5rem);
+}
+
+/* ===== Editorial Card ===== */
+.editorial-card {
+  display: flex;
+  flex-direction: column;
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  background: var(--color-bg);
+  border: 1px solid var(--color-border);
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+
+.editorial-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-3px);
+}
+
+.editorial-card--featured {
+  grid-row: 1 / 3;
+}
+
+.editorial-card__image-wrap {
+  position: relative;
+  overflow: hidden;
+  flex-shrink: 0;
+}
+
+.editorial-card--featured .editorial-card__image-wrap {
+  aspect-ratio: 4/5;
+}
+
+.editorial-card:not(.editorial-card--featured) .editorial-card__image-wrap {
+  aspect-ratio: 16/9;
+}
+
+.editorial-card__img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transition: transform var(--transition-slow);
+}
+
+.editorial-card:hover .editorial-card__img { transform: scale(1.05); }
+
+.editorial-card__category-pill {
+  position: absolute;
+  top: 1rem;
+  left: 1rem;
+  background: rgba(255,255,255,0.92);
+  border-radius: var(--radius-full);
+  padding: 0.25rem 0.75rem;
+  font-size: 0.7rem;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--color-brand);
+}
+
+.editorial-card__body {
+  padding: clamp(1rem, 2vw, 1.5rem);
+  display: flex;
+  flex-direction: column;
+  gap: 0.5rem;
+  flex: 1;
+}
+
+.editorial-card__meta {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+  font-size: 0.75rem;
+  color: var(--color-text-muted);
+}
+
+.editorial-card__meta-dot {
+  width: 3px;
+  height: 3px;
+  border-radius: 50%;
+  background: var(--color-text-muted);
+  flex-shrink: 0;
+}
+
+.editorial-card__title {
+  font-family: var(--font-serif);
+  font-size: clamp(1.0625rem, 1.5vw, 1.25rem);
+  font-weight: 600;
+  line-height: 1.3;
+  color: var(--color-brand);
+  transition: color var(--transition);
+}
+
+.editorial-card:hover .editorial-card__title { color: var(--color-accent-dark); }
+
+.editorial-card--featured .editorial-card__title {
+  font-size: clamp(1.25rem, 2vw, 1.625rem);
+}
+
+.editorial-card__excerpt {
+  font-size: 0.875rem;
+  color: var(--color-text-secondary);
+  line-height: 1.65;
+  display: -webkit-box;
+  -webkit-line-clamp: 3;
+  -webkit-box-orient: vertical;
+  overflow: hidden;
+}
+
+.editorial-card__link {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.375rem;
+  margin-top: auto;
+  padding-top: 0.75rem;
+  font-size: 0.8125rem;
+  font-weight: 600;
+  color: var(--color-brand);
+  transition: gap var(--transition), color var(--transition);
+}
+
+.editorial-card__link:hover {
+  gap: 0.625rem;
+  color: var(--color-accent-dark);
+}
+
+.editorial-card__link:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 3px;
+  border-radius: 2px;
+}
+
+/* ===== Newsletter ===== */
+.newsletter {
+  background: linear-gradient(135deg, #1c1612 0%, #2d2118 100%);
+  color: white;
+  padding-block: clamp(3.5rem, 7vw, 5.5rem);
+  text-align: center;
+}
+
+.newsletter__inner { max-width: 560px; margin-inline: auto; }
+
+.newsletter .section-eyebrow { color: var(--color-accent); }
+.newsletter .section-title { color: white; }
+.newsletter .section-desc { color: rgba(255,255,255,0.65); margin-inline: auto; }
+
+.newsletter__form {
+  display: flex;
+  gap: 0.625rem;
+  margin-top: 2rem;
+  max-width: 480px;
+  margin-inline: auto;
+}
+
+.newsletter__input-wrap { flex: 1; position: relative; }
+
+.newsletter__label {
+  position: absolute;
+  width: 1px; height: 1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+}
+
+.newsletter__input {
+  width: 100%;
+  padding: 0.8125rem 1.125rem;
+  background: rgba(255,255,255,0.08);
+  border: 1.5px solid rgba(255,255,255,0.18);
+  border-radius: var(--radius-md);
+  color: white;
+  font-size: 0.9375rem;
+  transition: border-color var(--transition), background var(--transition);
+}
+
+.newsletter__input::placeholder { color: rgba(255,255,255,0.38); }
+
+.newsletter__input:focus {
+  outline: none;
+  border-color: rgba(255,255,255,0.55);
+  background: rgba(255,255,255,0.12);
+}
+
+.newsletter__input:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.newsletter__input[aria-invalid="true"] {
+  border-color: #f87171;
+}
+
+.newsletter__error {
+  font-size: 0.8rem;
+  color: #f87171;
+  text-align: left;
+  margin-top: 0.375rem;
+}
+
+.newsletter__btn {
+  padding: 0.8125rem 1.5rem;
+  background: var(--color-accent);
+  color: #1c1612;
+  border-radius: var(--radius-md);
+  font-size: 0.875rem;
+  font-weight: 700;
+  letter-spacing: 0.03em;
+  transition: background var(--transition), transform var(--transition-fast);
+  white-space: nowrap;
+  border: 2px solid var(--color-accent);
+}
+
+.newsletter__btn:hover {
+  background: #c9a05e;
+  border-color: #c9a05e;
+  transform: translateY(-1px);
+}
+
+.newsletter__btn:focus-visible {
+  outline: 2px solid white;
+  outline-offset: 3px;
+}
+
+.newsletter__privacy {
+  margin-top: 1rem;
+  font-size: 0.75rem;
+  color: rgba(255,255,255,0.4);
+}
+
+.newsletter__success {
+  display: none;
+  align-items: center;
+  justify-content: center;
+  gap: 0.625rem;
+  margin-top: 2rem;
+  padding: 1rem 1.5rem;
+  background: rgba(255,255,255,0.08);
+  border: 1.5px solid rgba(255,255,255,0.18);
+  border-radius: var(--radius-md);
+  color: rgba(255,255,255,0.85);
+  font-size: 0.9375rem;
+}
+
+.newsletter__success.is-visible { display: flex; }
+
+/* ===== Footer ===== */
+.site-footer {
+  background: var(--color-brand);
+  color: rgba(255,255,255,0.72);
+  padding-block: clamp(3rem, 5vw, 4.5rem) 2rem;
+}
+
+.footer-top {
+  display: grid;
+  grid-template-columns: 1.5fr 1fr 1fr 1fr;
+  gap: clamp(2rem, 4vw, 4rem);
+  padding-bottom: 3rem;
+  border-bottom: 1px solid rgba(255,255,255,0.1);
+}
+
+.footer-brand__logo {
+  font-family: var(--font-serif);
+  font-size: 1.25rem;
+  font-weight: 600;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: white;
+  display: block;
+  margin-bottom: 1rem;
+}
+
+.footer-brand__desc {
+  font-size: 0.875rem;
+  line-height: 1.7;
+  margin-bottom: 1.5rem;
+  max-width: 280px;
+}
+
+.footer-social {
+  display: flex;
+  gap: 0.625rem;
+}
+
+.footer-social__link {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  width: 36px;
+  height: 36px;
+  border-radius: var(--radius-md);
+  background: rgba(255,255,255,0.08);
+  color: rgba(255,255,255,0.65);
+  transition: background var(--transition), color var(--transition);
+}
+
+.footer-social__link:hover {
+  background: rgba(255,255,255,0.15);
+  color: white;
+}
+
+.footer-social__link:focus-visible {
+  outline: 2px solid white;
+  outline-offset: 3px;
+}
+
+.footer-col__heading {
+  font-size: 0.75rem;
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: white;
+  margin-bottom: 1.25rem;
+}
+
+.footer-col__links {
+  display: flex;
+  flex-direction: column;
+  gap: 0.625rem;
+}
+
+.footer-col__link {
+  font-size: 0.875rem;
+  color: rgba(255,255,255,0.6);
+  transition: color var(--transition);
+}
+
+.footer-col__link:hover { color: white; }
+
+.footer-col__link:focus-visible {
+  outline: 2px solid white;
+  outline-offset: 3px;
+  border-radius: 2px;
+}
+
+.footer-bottom {
+  padding-top: 2rem;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: 1rem;
+}
+
+.footer-bottom__copy {
+  font-size: 0.8125rem;
+  color: rgba(255,255,255,0.4);
+}
+
+.footer-bottom__links {
+  display: flex;
+  gap: 1.5rem;
+}
+
+.footer-bottom__link {
+  font-size: 0.8125rem;
+  color: rgba(255,255,255,0.45);
+  transition: color var(--transition);
+}
+
+.footer-bottom__link:hover { color: white; }
+
+.footer-bottom__link:focus-visible {
+  outline: 2px solid white;
+  outline-offset: 3px;
+  border-radius: 2px;
+}
+
+/* ===== Cart Drawer ===== */
+.cart-drawer {
+  position: fixed;
+  inset: 0;
+  z-index: 500;
+}
+
+.cart-drawer[hidden] { display: none; }
+
+.cart-drawer__backdrop {
+  position: absolute;
+  inset: 0;
+  background: rgba(0,0,0,0.4);
+}
+
+.cart-drawer__panel {
+  position: absolute;
+  top: 0;
+  right: 0;
+  bottom: 0;
+  width: min(420px, 95vw);
+  background: var(--color-surface);
+  box-shadow: var(--shadow-xl);
+  display: flex;
+  flex-direction: column;
+  overflow: hidden;
+}
+
+.cart-drawer__header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 1.25rem 1.5rem;
+  border-bottom: 1px solid var(--color-border);
+}
+
+.cart-drawer__title {
+  font-family: var(--font-serif);
+  font-size: 1.25rem;
+  font-weight: 600;
+}
+
+.cart-drawer__body {
+  flex: 1;
+  overflow-y: auto;
+  padding: 1.5rem;
+}
+
+.cart-empty {
+  text-align: center;
+  color: var(--color-text-muted);
+  padding-block: 2rem;
+}
+
+.cart-item {
+  display: grid;
+  grid-template-columns: 72px 1fr;
+  gap: 1rem;
+  padding-block: 1rem;
+  border-bottom: 1px solid var(--color-border);
+}
+
+.cart-item__img {
+  width: 72px;
+  height: 90px;
+  object-fit: cover;
+  border-radius: var(--radius-sm);
+  background: var(--color-surface-alt);
+}
+
+.cart-item__info { display: flex; flex-direction: column; gap: 0.25rem; }
+
+.cart-item__name { font-size: 0.9rem; font-weight: 500; }
+
+.cart-item__price { font-size: 0.875rem; font-weight: 600; }
+
+.cart-item__remove {
+  font-size: 0.75rem;
+  color: var(--color-text-muted);
+  text-decoration: underline;
+  cursor: pointer;
+  background: none;
+  border: none;
+  padding: 0;
+  font-family: inherit;
+  transition: color var(--transition);
+}
+
+.cart-item__remove:hover { color: var(--color-sale); }
+
+.cart-drawer__footer {
+  border-top: 1px solid var(--color-border);
+  padding: 1.25rem 1.5rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.875rem;
+}
+
+.cart-total {
+  display: flex;
+  justify-content: space-between;
+  font-weight: 600;
+  font-size: 1rem;
+}
+
+.cart-note {
+  font-size: 0.75rem;
+  color: var(--color-text-muted);
+  text-align: center;
+}
+
+/* ===== Search Overlay ===== */
+.search-overlay {
+  position: fixed;
+  inset: 0;
+  z-index: 400;
+}
+
+.search-overlay[hidden] { display: none; }
+
+.search-overlay__backdrop {
+  position: absolute;
+  inset: 0;
+  background: rgba(0,0,0,0.5);
+}
+
+.search-overlay__panel {
+  position: absolute;
+  top: 0;
+  left: 0;
+  right: 0;
+  background: var(--color-surface);
+  padding: 1.5rem var(--container-pad);
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+  box-shadow: var(--shadow-lg);
+  max-width: var(--container-max);
+  margin-inline: auto;
+}
+
+.search-form { display: flex; align-items: center; flex: 1; gap: 0.75rem; }
+
+.search-input {
+  flex: 1;
+  padding: 0.75rem 0;
+  border: none;
+  border-bottom: 2px solid var(--color-border-strong);
+  background: transparent;
+  font-size: 1.125rem;
+  color: var(--color-text-primary);
+  transition: border-color var(--transition);
+}
+
+.search-input:focus {
+  outline: none;
+  border-bottom-color: var(--color-brand);
+}
+
+.search-submit {
+  color: var(--color-text-secondary);
+  transition: color var(--transition);
+  padding: 0.5rem;
+  border-radius: var(--radius-sm);
+}
+
+.search-submit:hover { color: var(--color-brand); }
+
+.search-submit:focus-visible {
+  outline: 2px solid var(--color-brand);
+  outline-offset: 3px;
+}
+
+/* ===== Live Region ===== */
+.live-region {
+  position: absolute;
+  width: 1px; height: 1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap;
+}
+
+/* ===== Responsive ===== */
+@media (max-width: 1100px) {
+  .products-grid { grid-template-columns: repeat(3, 1fr); }
+  .footer-top { grid-template-columns: 1fr 1fr; }
+}
+
+@media (max-width: 900px) {
+  .category-rail { grid-template-columns: repeat(3, 1fr); }
+  .deals-grid { grid-template-columns: repeat(2, 1fr); }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .editorial-card--featured { grid-column: 1 / -1; }
+  .editorial-card--featured .editorial-card__image-wrap { aspect-ratio: 16/7; }
+}
+
+@media (max-width: 768px) {
+  :root { --header-height: 56px; }
+
+  .header-nav { display: none; }
+  .mobile-menu-btn { display: flex; }
+  .header-inner { grid-template-columns: auto 1fr auto; }
+  .header-logo { justify-self: center; }
+
+  .products-grid { grid-template-columns: repeat(2, 1fr); }
+  .category-rail { grid-template-columns: repeat(3, 1fr); }
+}
+
+@media (max-width: 600px) {
+  .footer-top { grid-template-columns: 1fr 1fr; }
+  .footer-brand { grid-column: 1 / -1; }
+  .announcement-bar__inner { font-size: 0.7rem; gap: 0.75rem; }
+  .hero__actions { flex-direction: column; align-items: flex-start; }
+  .newsletter__form { flex-direction: column; }
+  .newsletter__btn { width: 100%; }
+  .deals-header { flex-direction: column; align-items: flex-start; }
+  .footer-bottom { flex-direction: column; align-items: center; text-align: center; }
+  .footer-bottom__links { justify-content: center; flex-wrap: wrap; gap: 1rem; }
+  .category-rail { grid-template-columns: repeat(2, 1fr); }
+}
+
+@media (max-width: 480px) {
+  .products-grid { grid-template-columns: repeat(2, 1fr); gap: 0.75rem; }
+  .deals-grid { grid-template-columns: 1fr 1fr; gap: 0.75rem; }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .editorial-card--featured .editorial-card__image-wrap { aspect-ratio: 16/9; }
+}
+
+@media (max-width: 360px) {
+  .products-grid { grid-template-columns: 1fr; }
+  .deals-grid { grid-template-columns: 1fr; }
