:root {
  --color-brand:           #111110;
  --color-accent:          #b5914e;
  --color-accent-dark:     #8a6d38;
  --color-sale:            #b91c1c;
  --color-sale-bg:         #fef2f2;
  --color-bg:              #fafaf9;
  --color-surface:         #ffffff;
  --color-surface-alt:     #f5f4f2;
  --color-border:          #e5e2dd;
  --color-border-strong:   #ccc8c2;
  --color-text-primary:    #111110;
  --color-text-secondary:  #57534e;
  --color-text-muted:      #a8a29e;
  --color-text-inverse:    #fafaf9;

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;

  --shadow-xs: 0 1px 2px rgba(0,0,0,.05);
  --shadow-sm: 0 1px 4px rgba(0,0,0,.07), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md: 0 4px 16px rgba(0,0,0,.09), 0 2px 6px rgba(0,0,0,.05);
  --shadow-lg: 0 12px 40px rgba(0,0,0,.13), 0 4px 12px rgba(0,0,0,.07);
  --shadow-xl: 0 24px 64px rgba(0,0,0,.16);

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  12px;
  --radius-xl:  20px;
  --radius-full: 9999px;

  --transition-fast: 120ms ease;
  --transition:      200ms ease;
  --transition-slow: 350ms ease;

  --container-max: 1280px;
  --container-pad: clamp(1rem, 4vw, 2.5rem);

  --header-height: 64px;
  --announcement-height: 40px;
}

/* ===== Reset ===== */
*,
*::before,
*::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img, video { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

ul { list-style: none; }

button {
  cursor: pointer;
  border: none;
  background: none;
  font: inherit;
  color: inherit;
}

input, select, textarea {
  font: inherit;
  color: inherit;
}

/* ===== Utilities ===== */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.container {
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-pad);
}

.section {
  padding-block: clamp(3rem, 6vw, 5rem);
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -100px;
  left: 1rem;
  z-index: 1000;
  padding: 0.625rem 1.25rem;
  background: var(--color-brand);
  color: var(--color-text-inverse);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  transition: top var(--transition-fast);
  outline: 3px solid transparent;
}

.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

/* ===== Focus Styles ===== */
:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 3px;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  transition: background var(--transition), color var(--transition),
              transform var(--transition-fast), box-shadow var(--transition);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
}

.btn:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

.btn--primary {
  background: var(--color-brand);
  color: var(--color-text-inverse);
  border: 2px solid var(--color-brand);
}

.btn--primary:hover {
  background: #2c2c2a;
  border-color: #2c2c2a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn--primary:active { transform: translateY(0); }

.btn--outline {
  background: transparent;
  color: var(--color-text-inverse);
  border: 2px solid rgba(255,255,255,0.7);
}

.btn--outline:hover {
  background: rgba(255,255,255,0.12);
  border-color: white;
}

.btn--outline-dark {
  background: transparent;
  color: var(--color-brand);
  border: 2px solid var(--color-brand);
}

.btn--outline-dark:hover {
  background: var(--color-brand);
  color: var(--color-text-inverse);
}

.btn--ghost {
  background: transparent;
  color: var(--color-brand);
  border: 2px solid transparent;
  padding-inline: 0.25rem;
}

.btn--ghost:hover { color: var(--color-accent-dark); }

.btn--full { width: 100%; }

.btn--sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.8125rem;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  color: var(--color-text-primary);
  transition: background var(--transition), color var(--transition);
  position: relative;
}

.icon-btn:hover { background: var(--color-surface-alt); }

.icon-btn:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 2px;
}

/* ===== Announcement Bar ===== */
.announcement-bar {
  background: var(--color-brand);
  color: var(--color-text-inverse);
  text-align: center;
  padding: 0;
  height: var(--announcement-height);
  display: flex;
  align-items: center;
  justify-content: center;
}

.announcement-bar__inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  font-weight: 500;
  text-transform: uppercase;
}

.announcement-bar__divider {
  opacity: 0.4;
  font-size: 0.7rem;
}

/* ===== Header ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.96);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  height: var(--header-height);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 100%;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-brand);
  text-decoration: none;
}

.header-logo__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.header-nav__link {
  padding: 0.4rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  letter-spacing: 0.01em;
}

.header-nav__link:hover {
  color: var(--color-brand);
  background: var(--color-surface-alt);
}

.header-nav__link:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 2px;
}

.header-nav__link--sale { color: var(--color-sale); }
.header-nav__link--sale:hover { color: var(--color-sale); background: var(--color-sale-bg); }

.header-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.25rem;
}

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  background: var(--color-sale);
  color: white;
  border-radius: var(--radius-full);
  font-size: 0.65rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-inline: 4px;
  line-height: 1;
  pointer-events: none;
}

.cart-badge[data-count="0"] { display: none; }

.mobile-menu-btn { display: none; }

/* ===== Mobile Nav Drawer ===== */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 200;
}

.mobile-nav.is-open { display: block; }

.mobile-nav__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.4);
}

.mobile-nav__panel {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: min(320px, 85vw);
  background: var(--color-surface);
  overflow-y: auto;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mobile-nav__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mobile-nav__logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.mobile-nav__links {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mobile-nav__link {
  display: block;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: background var(--transition), color var(--transition);
}

.mobile-nav__link:hover { background: var(--color-surface-alt); }
.mobile-nav__link--sale { color: var(--color-sale); }

/* ===== Hero ===== */
.hero {
  position: relative;
  min-height: clamp(480px, 65vh, 720px);
  display: flex;
  align-items: center;
  overflow: hidden;
  background: #1c1612;
}

.hero__bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(110deg,
      rgba(18,14,10,0.88) 0%,
      rgba(18,14,10,0.55) 50%,
      rgba(18,14,10,0.2) 100%),
    url('https://picsum.photos/seed/luminary-hero/1400/720') center/cover no-repeat;
  transform: scale(1.02);
  transition: transform 8s ease;
}

.hero:hover .hero__bg { transform: scale(1.0); }

.hero__content {
  position: relative;
  z-index: 1;
  max-width: 600px;
  padding-block: 4rem;
}

.hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 1.25rem;
}

.hero__eyebrow::before {
  content: '';
  display: block;
  width: 28px;
  height: 1px;
  background: var(--color-accent);
}

.hero__heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 5.5vw, 4rem);
  font-weight: 600;
  line-height: 1.1;
  color: white;
  margin-bottom: 1.25rem;
  letter-spacing: -0.01em;
}

.hero__heading em {
  font-style: italic;
  color: #d4b87a;
}

.hero__subtext {
  font-size: clamp(1rem, 1.5vw, 1.125rem);
  color: rgba(255,255,255,0.8);
  max-width: 440px;
  margin-bottom: 2.25rem;
  font-weight: 300;
  line-height: 1.7;
}

.hero__actions {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero__scroll-hint {
  position: absolute;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  color: rgba(255,255,255,0.5);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.hero__scroll-arrow {
  width: 20px;
  height: 20px;
  animation: bounceDown 1.6s ease infinite;
}

@keyframes bounceDown {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(6px); }
}

/* ===== Section Header ===== */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: clamp(1.5rem, 3vw, 2.5rem);
  gap: 1rem;
  flex-wrap: wrap;
}

.section-header--center {
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.section-eyebrow {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent-dark);
  margin-bottom: 0.5rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.625rem, 3vw, 2.25rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--color-brand);
}

.section-desc {
  color: var(--color-text-secondary);
  font-size: 1rem;
  max-width: 520px;
  margin-top: 0.625rem;
  line-height: 1.65;
}

.view-all-link {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-brand);
  letter-spacing: 0.02em;
  padding-bottom: 1px;
  border-bottom: 1.5px solid var(--color-brand);
  transition: color var(--transition), border-color var(--transition), gap var(--transition);
  white-space: nowrap;
}

.view-all-link:hover {
  color: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
  gap: 0.625rem;
}

.view-all-link:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 3px;
  border-bottom-color: transparent;
}

/* ===== Category Rail ===== */
.categories {
  background: var(--color-surface);
  padding-block: clamp(2rem, 4vw, 3rem);
  border-bottom: 1px solid var(--color-border);
}

.category-rail {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1rem;
}

.category-card {
  display: block;
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 3/4;
  text-decoration: none;
  background: var(--color-surface-alt);
}

.category-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0) 55%);
  transition: opacity var(--transition);
}

.category-card:hover::after { opacity: 0.85; }

.category-card:focus-visible {
  outline: 3px solid var(--color-brand);
  outline-offset: 3px;
}

.category-card__bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  transition: transform var(--transition-slow);
}

.category-card:hover .category-card__bg { transform: scale(1.06); }

.category-card__label {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1;
  padding: 1.25rem 1rem 1rem;
  color: white;
}

.category-card__name {
  font-family: var(--font-serif);
  font-size: clamp(1rem, 1.5vw, 1.1875rem);
  font-weight: 600;
  display: block;
}

.category-card__count {
  font-size: 0.75rem;
  opacity: 0.8;
  font-weight: 400;
  letter-spacing: 0.03em;
  margin-top: 0.125rem;
  display: block;
}

/* ===== Products Grid ===== */
.featured-products {
  background: var(--color-bg);
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(1rem, 2vw, 1.5rem);
}

/* ===== Product Card ===== */
.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--color-border);
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.product-card__image-wrap {
  position: relative;
  aspect-ratio: 3/4;
  overflow: hidden;
  background: var(--color-surface-alt);
}

.product-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.product-card:hover .product-card__img { transform: scale(1.05); }

.product-card__badges {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.badge {
  display: inline-block;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.badge--new      { background: var(--color-brand); color: white; }
.badge--sale     { background: var(--color-sale);  color: white; }
.badge--trending { background: var(--color-accent); color: #1c1612; }
.badge--limited  { background: #7c3aed; color: white; }

.product-card__wishlist {
  position: absolute;
  top: 0.625rem;
  right: 0.625rem;
  background: white;
  border-radius: var(--radius-full);
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: background var(--transition), color var(--transition), transform var(--transition-fast);
  color: var(--color-text-muted);
}

.product-card__wishlist:hover {
  color: var(--color-sale);
  transform: scale(1.1);
}

.product-card__wishlist.is-wishlisted { color: var(--color-sale); }

.product-card__wishlist svg { pointer-events: none; }

.product-card__wishlist.is-wishlisted svg { fill: currentColor; }

.product-card__wishlist:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 2px;
}

.product-card__body {
  padding: 1rem 1.125rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  flex: 1;
}

.product-card__category {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.product-card__name {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-brand);
  line-height: 1.35;
}

.product-card__rating {
  display: flex;
  align-items: center;
  gap: 0.375rem;
}

.stars {
  display: flex;
  align-items: center;
  gap: 1px;
  color: var(--color-text-muted);
}

.star { font-size: 0.8rem; }
.star--filled { color: #d4a017; }

.review-count {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

.product-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.5rem;
  gap: 0.5rem;
}

.product-card__price {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}

.price-current {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--color-brand);
}

.price-original {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}

.price-sale {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--color-sale);
}

.add-to-cart-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.5rem 0.875rem;
  background: var(--color-brand);
  color: white;
  border-radius: var(--radius-md);
  font-size: 0.78rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition-fast);
  white-space: nowrap;
}

.add-to-cart-btn:hover {
  background: #2c2c2a;
  transform: translateY(-1px);
}

.add-to-cart-btn:active { transform: translateY(0); }

