+  .category-rail { grid-template-columns: repeat(2, 1fr); }
+}
+
+@media (max-width: 480px) {
+  .products-grid { grid-template-columns: repeat(2, 1fr); gap: 0.75rem; }
+  .deals-grid { grid-template-columns: 1fr 1fr; gap: 0.75rem; }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .editorial-card--featured .editorial-card__image-wrap { aspect-ratio: 16/9; }
+}
+
+@media (max-width: 360px) {
+  .products-grid { grid-template-columns: 1fr; }
+  .deals-grid { grid-template-columns: 1fr; }
+  .category-rail { grid-template-columns: repeat(2, 1fr); }
+}
+
+/* ===== Forced Colors ===== */
+@media (forced-colors: active) {
+  .btn--primary { forced-color-adjust: none; background: ButtonText; color: ButtonFace; border-color: ButtonText; }
+  .badge { forced-color-adjust: none; }
+  .cart-badge { forced-color-adjust: none; background: Highlight; color: HighlightText; }
+  .hero__bg { display: none; }
+  .hero { background: Canvas; min-height: 300px; }
+  .hero__heading, .hero__subtext { color: CanvasText; }
+  .deals { background: Canvas; }
+  .deals .section-title { color: CanvasText; }
+  .newsletter { background: Canvas; }
+  .newsletter .section-title { color: CanvasText; }
+  .site-footer { background: Canvas; }
+  .category-card__bg { display: none; }
+  .category-card { background: Canvas; border: 1px solid ButtonText; }
+  .category-card__name { color: CanvasText; }
+  .product-card__wishlist.is-wishlisted svg { fill: none; }
+  .star--filled { forced-color-adjust: none; color: ButtonText; }
+}
+
+/* ===== Reduce Motion ===== */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after {
+    animation-duration: 0.01ms !important;
+    animation-iteration-count: 1 !important;
+    transition-duration: 0.01ms !important;
+  }
+  .hero:hover .hero__bg { transform: none; }
+}
+
